package lesson

import (
	"fmt"
	"net/http"
)

func Routes() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /posts/{id}", func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, r.PathValue("id")) })
	return mux
}
```

**routes_test.go**

```go
package lesson

import (
	"net/http/httptest"
	"testing"
)

func TestRouteContract(t *testing.T) {
	for _, test := range []struct {
		method, path string
		status       int
	}{{"GET", "/posts/42", 200}, {"POST", "/posts/42", 405}, {"GET", "/posts/42/comments", 404}} {
		recorder := httptest.NewRecorder()
		Routes().ServeHTTP(recorder, httptest.NewRequest(test.method, test.path, nil))
		if recorder.Code != test.status {
			t.Fatalf("%s %s: %d", test.method, test.path, recorder.Code)
		}
	}
}
```

**Run it**

```bash
go test -race ./...
go vet ./...
```

The table test proves 200, 405, and 404 as routing outcomes rather than calling the endpoint function directly.

