package lesson

import (
	"encoding/json"
	"log"
	"net/http"
)

func Routes() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /users/{id}", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if err := json.NewEncoder(w).Encode(map[string]string{"id": r.PathValue("id")}); err != nil {
			log.Printf("write user response: %v", err)
		}
	})
	return mux
}
```

**users_test.go**

```go
package lesson

import (
	"net/http/httptest"
	"testing"
)

func TestRoutes(t *testing.T) {
	for _, test := range []struct {
		method, path string
		want         int
	}{{"GET", "/users/42", 200}, {"POST", "/users/42", 405}, {"GET", "/missing", 404}} {
		recorder := httptest.NewRecorder()
		Routes().ServeHTTP(recorder, httptest.NewRequest(test.method, test.path, nil))
		if recorder.Code != test.want {
			t.Errorf("%s %s: got %d want %d", test.method, test.path, recorder.Code, test.want)
		}
	}
}
```

**Run it**

```bash
go test -race ./...
go vet ./...
```

Every case constructs the actual route graph, so method and path outcomes come from ServeMux rather than hand-built test state.
